(() => {
  let active = false;
  let lastTime = performance.now();
  let frameCount = 0;
  let currentHz = 0;
  let traces = { left: [], right: [] };
  let restingSamples = [];

  const connectPrompt = document.getElementById('gp-connect-prompt');
  const workspace = document.getElementById('gp-workspace');
  const devName = document.getElementById('gp-dev-name');
  const apiBadge = document.getElementById('gp-api-badge');
  const pollingHzEl = document.getElementById('gp-polling-hz');
  const circErrEl = document.getElementById('gp-circ-err');
  const circRatingEl = document.getElementById('gp-circ-rating');
  const offsetValEl = document.getElementById('gp-offset-val');
  const deadzoneRecEl = document.getElementById('gp-deadzone-rec');
  const leftCoordsEl = document.getElementById('gp-left-coords');
  const rightCoordsEl = document.getElementById('gp-right-coords');
  const triggerLVal = document.getElementById('gp-trigger-l-val');
  const triggerLBar = document.getElementById('gp-trigger-l-bar');
  const triggerRVal = document.getElementById('gp-trigger-r-val');
  const triggerRBar = document.getElementById('gp-trigger-r-bar');
  const clearTraceBtn = document.getElementById('gp-clear-trace-btn');
  const exportBtn = document.getElementById('gp-export-scorecard-btn');
  const webhidBtn = document.getElementById('gp-webhid-btn');

  const canvasL = document.getElementById('gp-canvas-left');
  const canvasR = document.getElementById('gp-canvas-right');
  const ctxL = canvasL.getContext('2d');
  const ctxR = canvasR.getContext('2d');

  function resizeCanvases() {
    const w = canvasL.parentElement.clientWidth || 300;
    canvasL.width = w * (window.devicePixelRatio || 1);
    canvasL.height = w * (window.devicePixelRatio || 1);
    canvasR.width = w * (window.devicePixelRatio || 1);
    canvasR.height = w * (window.devicePixelRatio || 1);
  }
  window.addEventListener('resize', resizeCanvases);

  function init() {
    connectPrompt.classList.add('hidden');
    workspace.classList.remove('hidden');
    resizeCanvases();
    active = true;
    requestAnimationFrame(loop);
  }

  window.addEventListener('gamepadconnected', (e) => {
    devName.textContent = e.gamepad.id.split('(')[0].trim() || 'Gamepad Device';
    init();
  });

  window.addEventListener('gamepaddisconnected', () => {
    active = false;
    connectPrompt.classList.remove('hidden');
    workspace.classList.add('hidden');
  });

  webhidBtn.addEventListener('click', async () => {
    if (navigator.hid) {
      try {
        const devices = await navigator.hid.requestDevice({ filters: [] });
        if (devices.length > 0) {
          apiBadge.textContent = 'WebHID Direct Telemetry Active';
          devName.textContent = devices[0].productName || 'WebHID Controller';
          init();
        }
      } catch (err) {}
    } else {
      alert('WebHID is supported in desktop Chromium browsers (Chrome, Edge). Using standard Gamepad API.');
    }
  });

  function drawOscilloscope(ctx, canvas, x, y, traceList) {
    const w = canvas.width;
    const h = canvas.height;
    const cx = w / 2;
    const cy = h / 2;
    const radius = cx * 0.85;

    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, w, h);

    // Crosshair
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx, 0); ctx.lineTo(cx, h);
    ctx.moveTo(0, cy); ctx.lineTo(w, cy);
    ctx.stroke();

    // Deadzone Circle (5% inner radius)
    ctx.strokeStyle = 'rgba(239, 68, 68, 0.4)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.05, 0, Math.PI * 2);
    ctx.stroke();

    // Unit Circle (1.0 theoretical outer boundary)
    ctx.strokeStyle = 'rgba(16, 185, 129, 0.4)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.stroke();

    // Persistent Trace
    traceList.push({ x, y });
    if (traceList.length > 500) traceList.shift();

    ctx.strokeStyle = 'rgba(56, 189, 248, 0.45)';
    ctx.lineWidth = 2 * (window.devicePixelRatio || 1);
    ctx.beginPath();
    traceList.forEach((p, idx) => {
      const px = cx + p.x * radius;
      const py = cy + p.y * radius;
      if (idx === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.stroke();

    // Active Position Dot
    const dotX = cx + x * radius;
    const dotY = cy + y * radius;
    const isDrifting = Math.sqrt(x * x + y * y) > 0.05;
    ctx.fillStyle = isDrifting ? '#ef4444' : '#38bdf8';
    ctx.beginPath();
    ctx.arc(dotX, dotY, 6 * (window.devicePixelRatio || 1), 0, Math.PI * 2);
    ctx.fill();
  }

  function loop(now) {
    if (!active) return;

    frameCount++;
    if (now - lastTime >= 1000) {
      currentHz = frameCount;
      pollingHzEl.textContent = String(currentHz);
      frameCount = 0;
      lastTime = now;
    }

    const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
    const gp = gamepads[0];

    if (gp) {
      const lx = gp.axes[0] || 0;
      const ly = gp.axes[1] || 0;
      const rx = gp.axes[2] || 0;
      const ry = gp.axes[3] || 0;

      leftCoordsEl.textContent = `X: ${lx.toFixed(4)} | Y: ${ly.toFixed(4)}`;
      rightCoordsEl.textContent = `X: ${rx.toFixed(4)} | Y: ${ry.toFixed(4)}`;

      drawOscilloscope(ctxL, canvasL, lx, ly, traces.left);
      drawOscilloscope(ctxR, canvasR, rx, ry, traces.right);

      // Triggers (Standard mapping: Button 6 = L2, Button 7 = R2)
      const l2Val = gp.buttons[6] ? gp.buttons[6].value : 0;
      const r2Val = gp.buttons[7] ? gp.buttons[7].value : 0;
      triggerLVal.textContent = Math.round(l2Val * 100) + '%';
      triggerLBar.style.width = Math.round(l2Val * 100) + '%';
      triggerRVal.textContent = Math.round(r2Val * 100) + '%';
      triggerRBar.style.width = Math.round(r2Val * 100) + '%';

      // Circularity Error on Left Stick when moved
      const magL = Math.sqrt(lx * lx + ly * ly);
      if (magL > 0.7) {
        const err = Math.abs(1.0 - magL) * 100;
        circErrEl.textContent = err.toFixed(1);
        if (err <= 5) {
          circRatingEl.textContent = 'Excellent (Near-Unit Circle)';
          circRatingEl.className = 'text-[10px] font-semibold text-emerald-600 block mt-0.5';
        } else if (err <= 15) {
          circRatingEl.textContent = 'Standard Controller Normal';
          circRatingEl.className = 'text-[10px] font-semibold text-slate-500 block mt-0.5';
        } else {
          circRatingEl.textContent = 'Square Gated / High Error';
          circRatingEl.className = 'text-[10px] font-semibold text-amber-600 block mt-0.5';
        }
      }

      // Resting Offset (sampling when magnitude < 0.2)
      if (magL < 0.2) {
        restingSamples.push({ x: lx, y: ly });
        if (restingSamples.length > 60) restingSamples.shift();
        const avgOffset = (restingSamples.reduce((acc, p) => acc + Math.sqrt(p.x * p.x + p.y * p.y), 0) / restingSamples.length) * 100;
        offsetValEl.textContent = avgOffset.toFixed(1);
        const recDeadzone = Math.max(2, Math.round(avgOffset + 3));
        deadzoneRecEl.textContent = `Rec. Deadzone: ${recDeadzone}%`;
      }
    }

    requestAnimationFrame(loop);
  }

  clearTraceBtn.addEventListener('click', () => {
    traces.left = [];
    traces.right = [];
  });

  exportBtn.addEventListener('click', () => {
    const report = [
      '=== ToolkitGen Gamepad Diagnostic Scorecard ===',
      `Date: ${new Date().toISOString().split('T')[0]}`,
      `Controller: ${devName.textContent}`,
      `Polling Frequency: ${pollingHzEl.textContent} Hz`,
      `Circularity Error: ${circErrEl.textContent}%`,
      `Resting Centering Offset: ${offsetValEl.textContent}%`,
      `${deadzoneRecEl.textContent}`,
      'Verification Result: ' + (parseFloat(offsetValEl.textContent) > 10 ? 'Drift Calibration Recommended' : 'Passed Precision Gate'),
      'Diagnostic URL: https://toolkitgen.com/tool/webhid_gamepad_diagnostics',
    ].join('\n');

    if (navigator.clipboard) {
      navigator.clipboard.writeText(report).then(() => alert('RMA Scorecard copied to clipboard!'));
    } else {
      prompt('Copy your scorecard:', report);
    }
  });
})();
